#include <stdio.h>

int main(void) {
    int arr[] = {10, 20, 30, 40};
    int *p = arr;
    printf("%d", *(p + 2) + *p);
    return 0;
}

public class Main {
    public static void main(String[] args) {
        int sum = 0;
        for (int i = 1; i <= 10; i++) {
            if (i % 3 == 0) continue;
            sum += i;
        }
        System.out.println(sum);
    }
}
